def is_valid_email(addr: str) -> bool:
    """Catch obvious typing mistakes: spaces, a missing name, or no dot in the domain."""
    if " " in addr or addr.count("@") != 1:
        return False
    name, domain = addr.split("@")
    return bool(name) and "." in domain.strip(".")

